-- ============================================================-- Olist E-Commerce Delivery Performance Analysis-- Complete SQL Script-- ============================================================-- ------------------------------------------------------------ PART 1: Create Clean Orders Table-- ----------------------------------------------------------DROP TABLE IF EXISTS orders_clean;CREATE TABLE orders_clean ASSELECT    order_id,    customer_id,    order_status,    DATE(order_purchase_timestamp) AS order_purchase_date,    DATE(order_estimated_delivery_date) AS order_estimated_delivery_date,    DATE(order_delivered_customer_date) AS order_delivered_customer_date,    JULIANDAY(order_delivered_customer_date) - JULIANDAY(order_estimated_delivery_date) AS delay_daysFROM ordersWHERE order_status = 'delivered'  AND order_delivered_customer_date <> ''  AND order_estimated_delivery_date <> '';-- ------------------------------------------------------------ PART 2: Create Enriched View with Delay Buckets-- ----------------------------------------------------------DROP VIEW IF EXISTS orders_enriched;CREATE VIEW orders_enriched ASSELECT    *,    CASE        WHEN delay_days <= 0 THEN 'On Time / Early'        WHEN delay_days <= 3 THEN '1-3 days'        WHEN delay_days <= 7 THEN '4-7 days'        ELSE '>7 days'    END AS delay_bucket,    CASE WHEN delay_days > 0 THEN 1 ELSE 0 END AS is_delayedFROM orders_clean;-- ------------------------------------------------------------ PART 3: Analytical Queries-- ------------------------------------------------------------ Q1: Monthly On-Time Delivery RateSELECT    strftime('%Y-%m', order_purchase_date) AS month,    ROUND(100.0 * SUM(CASE WHEN is_delayed = 0 THEN 1 ELSE 0 END) / COUNT(*), 2) AS on_time_pct,    COUNT(*) AS total_ordersFROM orders_enrichedGROUP BY monthORDER BY month;-- Q2: Average Delay by Product Category (English)SELECT    t.product_category_name_english,    ROUND(AVG(o.delay_days), 2) AS avg_delay_days,    COUNT(*) AS total_orders,    ROUND(SUM(o.is_delayed) * 100.0 / COUNT(*), 2) AS delayed_pctFROM orders_enriched oJOIN order_items oi ON o.order_id = oi.order_idJOIN products p ON oi.product_id = p.product_idJOIN product_category_name_translation t ON p.product_category_name = t.product_category_nameGROUP BY t.product_category_name_englishORDER BY avg_delay_days DESC;-- Q3: Seller Performance RankingSELECT    s.seller_id,    s.seller_city,    s.seller_state,    COUNT(o.order_id) AS orders_handled,    ROUND(AVG(o.delay_days), 2) AS avg_delay,    ROUND(SUM(o.is_delayed) * 100.0 / COUNT(*), 2) AS delay_pctFROM orders_enriched oJOIN order_items oi ON o.order_id = oi.order_idJOIN sellers s ON oi.seller_id = s.seller_idGROUP BY s.seller_idHAVING orders_handled > 50ORDER BY avg_delay DESC;-- Q4: On-Time Delivery by Customer State (for map)SELECT    c.customer_state,    COUNT(*) AS total_orders,    ROUND(SUM(o.is_delayed) * 100.0 / COUNT(*), 2) AS delayed_pct,    ROUND(AVG(o.delay_days), 2) AS avg_delayFROM orders_enriched oJOIN customers c ON o.customer_id = c.customer_idGROUP BY c.customer_stateORDER BY avg_delay DESC;-- Q5: Delivery Delay by Freight TierSELECT    CASE        WHEN oi.freight_value < 20 THEN 'Low freight'        WHEN oi.freight_value < 50 THEN 'Medium freight'        ELSE 'High freight'    END AS freight_tier,    COUNT(*) AS orders,    ROUND(AVG(o.delay_days), 2) AS avg_delayFROM orders_enriched oJOIN order_items oi ON o.order_id = oi.order_idGROUP BY freight_tierORDER BY avg_delay DESC;-- Q6: Weekly Rolling Average of Delay DaysSELECT    DATE(order_purchase_date, 'weekday 0', '-6 days') AS week_start,    ROUND(AVG(delay_days), 2) AS avg_delay_weekly,    COUNT(*) AS ordersFROM orders_enrichedGROUP BY week_startORDER BY week_start;-- Q7: Top 10 Cities with Worst Average DelaySELECT    c.customer_city,    c.customer_state,    COUNT(*) AS orders,    ROUND(AVG(o.delay_days), 2) AS avg_delayFROM orders_enriched oJOIN customers c ON o.customer_id = c.customer_idGROUP BY c.customer_city, c.customer_stateHAVING orders > 100ORDER BY avg_delay DESCLIMIT 10;-- Q8: Year-over-Year Quarterly On-Time %SELECT    strftime('%Y', order_purchase_date) AS year,    ((CAST(strftime('%m', order_purchase_date) AS INTEGER) - 1) / 3) + 1 AS quarter,    ROUND(100.0 * SUM(CASE WHEN is_delayed = 0 THEN 1 ELSE 0 END) / COUNT(*), 2) AS on_time_pct,    COUNT(*) AS total_ordersFROM orders_enrichedGROUP BY year, quarterORDER BY year, quarter;-- ------------------------------------------------------------ Q9: Combined Query for Tableau Export (joins all tables)-- ----------------------------------------------------------SELECT    o.order_id,    o.customer_id,    o.order_purchase_date,    o.order_estimated_delivery_date,    o.order_delivered_customer_date,    o.delay_days,    o.delay_bucket,    o.is_delayed,    oi.product_id,    oi.seller_id,    oi.price,    oi.freight_value,    t.product_category_name_english,    c.customer_state,    c.customer_cityFROM orders_enriched oJOIN order_items oi ON o.order_id = oi.order_idJOIN products p ON oi.product_id = p.product_idJOIN product_category_name_translation t ON p.product_category_name = t.product_category_nameJOIN customers c ON o.customer_id = c.customer_id;